'use strict';
const icons={games:'<rect x="4" y="3" width="7" height="18" rx="2"/><path d="M4 12h7m5-7 4 14M7 7h1m-1 10h1m8-7h1m1 6h1"/>',rooms:'<path d="M3 20V8l9-5 9 5v12M8 20v-7h8v7M2 20h20"/>',rating:'<path d="M8 3h8v7a4 4 0 0 1-8 0V3ZM8 5H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4m-4 2v6m-5 1h10"/>',history:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7m2-5v6l4 2"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',admin:'<path d="m12 3 8 4v6c0 4-8 8-8 8s-8-4-8-8V7l8-4Z"/><path d="m8 12 3 3 5-6"/>'};
const labels={games:'Ігри',rooms:'Кімнати',rating:'Рейтинг',history:'Історія',profile:'Профіль',admin:'Адмінпанель'};
document.getElementById('navigation').innerHTML=Object.entries(labels).map(([key,label])=>`<button class="nav-item ${key==='games'?'active':''}" data-action="navigate" data-page="${key}"><svg viewBox="0 0 24 24" aria-hidden="true">${icons[key]}</svg>${label}</button>`).join('');
const main=document.getElementById('main'),modal=document.getElementById('modal'),homeHTML=main.innerHTML;
const titles={classic:'Доміно · Класика',telephone:'Доміно · Телефон',lotto:'Лото'};
const botNames=['Марко','Софія','Денис'];
const defaults=()=>({version:1,profile:{name:'Гість',color:'rose'},balance:1000,history:[],rooms:[{id:'r1',name:'Золотий стіл',game:'classic',stake:10,seats:2,open:true},{id:'r2',name:'Вечірня партія',game:'telephone',stake:25,seats:4,open:true},{id:'r3',name:'Щасливий квиток',game:'lotto',stake:10,seats:4,open:true},{id:'r4',name:'Класика для друзів',game:'classic',stake:50,seats:4,open:true}]});
let state=defaults(),page='games',filter='all',activeGame=null,botTimer=null,lottoTimer=null,lottoPaused=false,toastTimer=null;
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('uk-UA').format(n);
const date=s=>new Date(s).toLocaleString('uk-UA',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
try{const saved=JSON.parse(localStorage.getItem('luxary-demo-v1'));if(saved?.version===1&&Number.isFinite(saved.balance)&&saved.balance>=0&&Array.isArray(saved.rooms)&&Array.isArray(saved.history)&&typeof saved.profile?.name==='string'&&saved.profile.name.length>0&&saved.rooms.every(r=>typeof r?.id==='string'&&typeof r.name==='string'&&Object.hasOwn(titles,r.game)&&[10,25,50,100].includes(r.stake)&&[2,4].includes(r.seats)&&typeof r.open==='boolean')&&saved.history.every(r=>r&&Object.hasOwn(titles,r.game)&&typeof r.room==='string'&&Number.isFinite(r.net)&&Number.isFinite(r.stake)&&!Number.isNaN(Date.parse(r.date)))){state=saved;state.history=state.history.slice(0,100).map(r=>r.status==='interrupted'?{...r,status:'loss'}:r);}}catch{}
function save(){try{localStorage.setItem('luxary-demo-v1',JSON.stringify(state));}catch{toast('Пам’ять браузера недоступна. Зміни діятимуть до закриття сторінки.');}updateAccount();}
function updateAccount(){document.getElementById('balance').textContent=fmt(state.balance);document.querySelector('.avatar').textContent=state.profile.name.slice(0,1).toUpperCase();document.querySelector('.avatar').className=`avatar ${state.profile.color||'rose'}`;}
function toast(message){clearTimeout(toastTimer);const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),4500);}
function showModal(title,body){document.getElementById('modal-content').innerHTML=`<div class="modal-body"><div class="modal-title"><h2>${title}</h2><button class="close-button" data-action="close" aria-label="Закрити діалог">×</button></div>${body}</div>`;if(!modal.open)modal.showModal();}
function heading(title,sub,action=''){return `<div class="page-heading"><div><p class="eyebrow">LUXARY GAMES / ДЕМО</p><h1>${title}</h1><p class="muted">${sub}</p></div>${action}</div>`;}
function roomRows(rooms,admin=false){if(!rooms.length)return '<div class="empty"><h2>Столів поки немає</h2><p>Створи кімнату або обери іншу гру.</p></div>';return `<div class="room-list">${rooms.map(r=>`<article class="room-row"><span class="room-emblem" aria-hidden="true">${r.game==='lotto'?'90':'◆'}</span><div><div class="room-name">${escapeHTML(r.name)}</div><div class="room-sub">${titles[r.game]}${r.open?'':' · Закрита'}</div></div><div class="room-stake">${fmt(r.stake)} <span class="coin">◆</span></div><div class="room-players">Ти + ${r.seats-1} ${r.seats===2?'бот':'боти'}</div><button class="button ${admin?'ghost':'gold'}" data-action="${admin?'toggle-room':'join'}" data-id="${r.id}" ${!r.open&&!admin?'disabled':''}>${admin?(r.open?'Закрити':'Відкрити'):'За стіл'}</button></article>`).join('')}</div>`;}
function navigate(next,gameFilter){if(activeGame&&!activeGame.settled&&next!=='play'){confirmLeave(()=>navigate(next,gameFilter));return;}if(!Object.hasOwn(labels,next)&&next!=='play')return;page=next;if(gameFilter)filter=gameFilter;document.querySelectorAll('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.page===next));render();window.scrollTo(0,0);}
function render(){
  updateAccount();if(page==='games'){main.innerHTML=homeHTML;document.getElementById('home-rooms').innerHTML=roomRows(state.rooms.filter(r=>r.open).slice(0,3));}
  if(page==='rooms'){main.innerHTML=heading('Кімнати для гри','Обирай стіл або створи свій. У демо місця займають боти.','<button class="button gold" data-action="create-room">Створити кімнату</button>')+`<div class="segmented" aria-label="Фільтр ігор">${[['all','Усі ігри'],['classic','Класика'],['telephone','Телефон'],['lotto','Лото']].map(([v,t])=>`<button class="filter ${filter===v?'active':''}" data-action="filter" data-filter="${v}" aria-pressed="${filter===v}">${t}</button>`).join('')}</div>`+roomRows(state.rooms.filter(r=>r.open&&(filter==='all'||r.game===filter)))+'<div class="demo-strip"><span class="strip-icon">◇</span><p>Внесок списується при вході. Переможець отримує банк столу. Вихід із незавершеної партії — поразка.</p></div>';}
  if(page==='profile')renderProfile();if(page==='history')renderHistory();if(page==='rating')renderRating();if(page==='admin')renderAdmin();if(page==='play')renderGame();
}
function rules(game='all'){
  const intro='<p>Це демонстрація з ботами та умовними фішками. Дані зберігаються лише в цьому браузері. Реєстрація, платежі й гра між різними пристроями не підключені.</p>';
  const classic='<h3>Доміно · Класика</h3><p>Кожен отримує 7 кісточок. Починає власник найстаршого дубля; без дублів — найстаршої кісточки. На початку можна викласти будь-яку кісточку. Стикуй однакові числа зліва або справа. Якщо ходу немає, бери з базару, доки з’явиться хід; коли базар порожній — пропускай.</p><p>Виграє той, хто першим викладе всі кісточки. Якщо всі пропускають («риба»), виграє найменша сума на руках. Кожен грає за себе.</p>';
  const phone='<h3>Доміно · Телефон — демо-правила</h3><p>Ходи як у класиці. Якщо сума відкритих кінців кратна 5, отримуєш стільки ж очок. Дубль на відкритому кінці рахується двічі. Один дубль на порожньому столі рахується один раз як сума двох половин.</p><p>Одна роздача. Гравець, який закінчив або має найменше очок на руках при «рибі», отримує суму кісточок суперників, округлену до найближчих 5. За рівності при «рибі» бонус отримує перший за порядком місць. Виграє найбільший підсумковий рахунок. Цей варіант правил можна змінити під замовника.</p>';
  const lotto='<h3>Лото</h3><p>Квиток має 3 рядки по 5 чисел. Ведучий витягує числа від 1 до 90 без повторів. Квитки позначаються автоматично. Виграє перший повністю закритий квиток; за одночасного виграшу банк ділиться порівну.</p><p>Розіграш можна призупинити або витягнути наступне число кнопкою.</p>';
  showModal('Правила клубу',intro+(game==='all'||game==='classic'?classic:'')+(game==='all'||game==='telephone'?phone:'')+(game==='all'||game==='lotto'?lotto:'')+'<h3>Фішки та вихід</h3><p>Банк складається з внесків усіх місць. Фішки ботів умовні. При нічиїй банк ділиться між переможцями з округленням вниз. Незавершена партія після виходу чи перезавантаження зараховується як поразка. Демо-фішки можна додати в гаманці.</p>');
}
function createRoom(){showModal('Новий стіл',`<form id="room-form"><label class="form-field">Назва кімнати<input name="name" maxlength="40" required value="Мій вечірній стіл"></label><label class="form-field">Гра<select name="game"><option value="classic">Доміно · Класика</option><option value="telephone">Доміно · Телефон</option><option value="lotto">Лото</option></select></label><label class="form-field">Внесок у фішках<select name="stake"><option value="10">10 фішок</option><option value="25">25 фішок</option><option value="50">50 фішок</option><option value="100">100 фішок</option></select></label><label class="form-field">Місць за столом<select name="seats"><option value="2">2 — ти та один бот</option><option value="4">4 — ти та три боти</option></select></label><p>Кімната збережеться у твоєму браузері.</p><div class="modal-actions"><button type="button" class="button ghost" data-action="close">Скасувати</button><button class="button gold" type="submit">Створити стіл</button></div></form>`);}
function joinRoom(id){const room=state.rooms.find(r=>r.id===id);if(!room?.open){toast('Ця кімната вже закрита');return;}if(activeGame&&!activeGame.settled){confirmLeave(()=>joinRoom(id));return;}if(state.balance<room.stake){wallet();toast('Потрібно більше демо-фішок');return;}showModal(escapeHTML(room.name),`<div class="lobby-game">${titles[room.game]}</div><div class="lobby-seats">${[state.profile.name,...botNames.slice(0,room.seats-1)].map((name,i)=>`<div class="lobby-player"><span class="avatar ${i?'bot-avatar':''}">${escapeHTML(name[0])}</span><strong>${escapeHTML(name)}</strong><span class="muted">${i?'Бот':'Ти'}</span></div>`).join('')}</div><div class="lobby-pot"><span>Внесок <strong>${room.stake} ◆</strong></span><span>Банк столу <strong>${room.stake*room.seats} ◆</strong></span></div><p>Готові до партії? При старті буде списано ${room.stake} умовних фішок.</p><div class="modal-actions"><button class="button ghost" data-action="close">Скасувати</button><button class="button gold" data-action="start" data-id="${room.id}">Почати гру</button></div>`);}
function startGame(id){if(activeGame&&!activeGame.settled)return;const room=state.rooms.find(r=>r.id===id);if(!room?.open||state.balance<room.stake){modal.close();toast('Стіл недоступний або бракує фішок');return;}clearTimers();const record={id:crypto.randomUUID(),date:new Date().toISOString(),game:room.game,room:room.name,stake:room.stake,net:-room.stake,status:'interrupted'};state.balance-=room.stake;state.history.unshift(record);state.history=state.history.slice(0,100);save();activeGame={room:{...room},recordId:record.id,names:[state.profile.name,...botNames.slice(0,room.seats-1)],engine:room.game==='lotto'?new GameEngine.Lotto(room.seats):new GameEngine.Domino(room.game,room.seats),settled:false,selected:null,logs:['Партія почалася.'],speed:2400};lottoPaused=false;modal.close();page='play';document.querySelectorAll('.nav-item').forEach(el=>el.classList.remove('active'));renderGame();schedule();}
function clearTimers(){clearTimeout(botTimer);clearTimeout(lottoTimer);botTimer=null;lottoTimer=null;}
function confirmLeave(after){showModal('Залишити партію?','<p>Внесок уже в банку столу. Якщо вийдеш зараз, партія буде зарахована як поразка.</p><div class="modal-actions"><button class="button gold" data-action="close">Продовжити гру</button><button class="button danger" id="leave-confirm">Залишити стіл</button></div>');document.getElementById('leave-confirm').onclick=()=>{clearTimers();activeGame.settled=true;const r=state.history.find(r=>r.id===activeGame.recordId);if(r)r.status='loss';save();modal.close();activeGame=null;after();};}
function settle(){const g=activeGame;if(!g||g.settled||!g.engine.finished)return;clearTimers();g.settled=true;const win=g.engine.winners.includes(0),payout=win?Math.floor(g.room.stake*g.room.seats/g.engine.winners.length):0;state.balance+=payout;const record=state.history.find(r=>r.id===g.recordId);if(record){record.status=win?(g.engine.winners.length>1?'draw':'win'):'loss';record.net=payout-g.room.stake;record.winners=g.engine.winners.map(i=>g.names[i]);record.scores=g.engine.scores||null;}save();}
function schedule(){const g=activeGame;if(!g||g.engine.finished){settle();if(g)renderGame();return;}if(g.room.game==='lotto'){if(!lottoPaused)lottoTimer=setTimeout(()=>{drawLotto();},g.speed);return;}if(g.engine.turn!==0)botTimer=setTimeout(()=>{if(!activeGame||activeGame!==g||g.engine.finished)return;const p=g.engine.turn;let attempts=0;do{g.engine.botMove();g.logs.unshift(`${g.names[p]}: ${g.engine.last}`);}while(g.engine.turn===p&&!g.engine.finished&&++attempts<28);g.logs=g.logs.slice(0,6);settle();renderGame();schedule();},850);}
function drawLotto(){clearTimeout(lottoTimer);const g=activeGame;if(!g||g.room.game!=='lotto'||g.engine.finished)return;g.engine.draw();settle();renderGame();schedule();}
function playerDomino(action,index,side){const g=activeGame;if(!g||g.room.game==='lotto'||g.engine.turn!==0||g.engine.finished)return;try{if(action==='play')g.engine.play(Number(index),side);if(action==='draw')g.engine.draw();if(action==='pass')g.engine.pass();g.selected=null;g.logs.unshift(`Ти: ${g.engine.last}`);g.logs=g.logs.slice(0,6);settle();renderGame();schedule();}catch(error){toast(error.message);}}
function pips(n){const spots={0:[],1:[4],2:[0,8],3:[0,4,8],4:[0,2,6,8],5:[0,2,4,6,8],6:[0,2,3,5,6,8]};return `<span class="pip-face" aria-hidden="true">${Array.from({length:9},(_,i)=>`<i class="${spots[n].includes(i)?'dot':''}"></i>`).join('')}</span>`;}
function tileHTML(t,button=false,index=0,legal=false,selected=false){return button?`<button class="domino-tile ${legal?'playable':''} ${selected?'selected':''}" data-action="select-tile" data-index="${index}" aria-label="Кісточка ${t.a}:${t.b}${legal?', доступний хід':''}" ${legal?'':'disabled'}>${pips(t.a)}<span class="tile-line"></span>${pips(t.b)}</button>`:`<span class="domino-tile horizontal ${t.a===t.b?'double':''}" role="img" aria-label="Кісточка ${t.a}:${t.b}">${pips(t.a)}<span class="tile-line"></span>${pips(t.b)}</span>`;}
function playerPanel(i){const g=activeGame,e=g.engine,current=g.room.game!=='lotto'&&e.turn===i&&!e.finished;return `<div class="table-player ${current?'current':''}"><span class="avatar ${i?'bot-avatar':''}">${escapeHTML(g.names[i][0])}</span><div><strong>${escapeHTML(g.names[i])}${i?' <span class="bot-tag">БОТ</span>':' <span class="bot-tag">ТИ</span>'}</strong><small>${g.room.game==='lotto'?`${e.matched(i)} / 15 чисел`:`${e.hands[i].length} кісточок${g.room.game==='telephone'?` · ${e.scores[i]} очок`:''}`}</small></div>${current?'<span class="turn-label">Хід</span>':''}</div>`;}
function renderGame(){const g=activeGame;if(!g){navigate('games');return;}const e=g.engine,isLotto=g.room.game==='lotto';main.innerHTML=heading(escapeHTML(g.room.name),`${titles[g.room.game]} · Банк ${fmt(g.room.stake*g.room.seats)} фішок`,`<div class="heading-actions"><button class="button ghost" data-action="game-rules">Правила</button><button class="button ghost" data-action="leave-game">Вийти</button></div>`)+`<section class="play-table ${isLotto?'lotto-table':''}"><div class="table-opponents">${g.names.slice(1).map((_,i)=>playerPanel(i+1)).join('')}</div>${isLotto?renderLottoBoard():renderDominoBoard()}${e.finished?resultHTML():''}</section>${isLotto?lottoControls():dominoControls()}`;}
function renderDominoBoard(){const g=activeGame,e=g.engine;return `<div class="board-summary"><span class="pill">${g.room.game==='telephone'?`ВІДКРИТІ КІНЦІ: ${e.openSum()}`:'ПАРТІЯ ДОМІНО'}</span><span>${e.finished?'Партію завершено':e.turn===0?'Твій хід':`${escapeHTML(g.names[e.turn])} обирає кісточку…`}</span><span class="stock-label">Базар: ${e.stock.length}</span></div><div class="domino-chain ${e.chain.length?'':'chain-empty'}" aria-label="Кісточки на столі">${e.chain.length?e.chain.map(t=>tileHTML(t)).join(''):'<span class="table-center-logo">◆<small>LUXARY GAMES</small><p>Перша кісточка відкриває партію</p></span>'}</div><div class="game-log" aria-live="polite">${escapeHTML(g.logs[0])}</div>`;}
function dominoControls(){const g=activeGame,e=g.engine;const legal=e.turn===0&&!e.finished?e.legal():[],selected=legal.find(m=>m.index===g.selected);return `<section class="hand-panel"><div class="hand-heading">${playerPanel(0)}<div class="hand-actions"><button class="button ghost" data-action="draw-tile" ${e.turn!==0||e.finished||legal.length||!e.stock.length?'disabled':''}>Взяти з базару</button><button class="button ghost" data-action="pass" ${e.turn!==0||e.finished||legal.length||e.stock.length?'disabled':''}>Пропустити</button></div></div><div class="player-hand" aria-label="Твої кісточки">${e.hands[0].map((t,i)=>tileHTML(t,true,i,legal.some(m=>m.index===i),g.selected===i)).join('')}</div><div class="move-controls">${selected?`<span>Куди викласти ${selected.tile.a}:${selected.tile.b}?</span>${selected.sides.includes('left')?`<button class="button gold" data-action="play-tile" data-side="left">Ліворуч</button>`:''}${selected.sides.includes('right')?`<button class="button gold" data-action="play-tile" data-side="right">${e.chain.length?'Праворуч':'Викласти'}</button>`:''}`:`<p class="muted">${e.finished?'Можна почати нову партію.':e.turn!==0?'Зачекай на свій хід.':legal.length?'Обери підсвічену кісточку, потім кінець столу.':e.stock.length?'Ходу немає. Візьми кісточку з базару.':'Ходу немає, базар порожній. Пропусти хід.'}</p>`}</div></section><details class="log-details"><summary>Останні ходи</summary>${g.logs.map(t=>`<p>${escapeHTML(t)}</p>`).join('')}</details>`;}
function renderLottoBoard(){const e=activeGame.engine,last=e.called.at(-1);return `<div class="lotto-draw"><div class="lotto-ball ${last?'':'waiting'}">${last||'?'}</div><div><span class="eyebrow">${last?'ЧИСЛО НА СТОЛІ':'РОЗІГРАШ ПОЧИНАЄТЬСЯ'}</span><h2>${e.finished?'Є переможець!':lottoPaused?'Розіграш на паузі':'Знайди число на квитку'}</h2><p class="muted">Витягнуто ${e.called.length} із 90 · Автоматичні позначки</p></div></div><div class="ticket-heading"><strong>Твій квиток</strong><span>${e.matched(0)} / 15</span></div><div class="lotto-ticket" aria-label="Твій квиток лото">${e.tickets[0].flat().map(n=>`<span class="ticket-cell ${n===null?'blank':''} ${e.called.includes(n)?'marked':''} ${n===last?'latest':''}" ${n!==null?`aria-label="${n}${e.called.includes(n)?', випало':''}"`:''}>${n??''}</span>`).join('')}</div><div class="called-balls" aria-label="Останні витягнуті числа">${e.called.slice(-12).reverse().map((n,i)=>`<span class="${i===0?'new':''}">${n}</span>`).join('')}</div>`;}
function lottoControls(){const e=activeGame.engine;return `<div class="lotto-controls"><button class="button gold" data-action="next-number" ${e.finished?'disabled':''}>Наступне число</button><button class="button ghost" data-action="pause-lotto" ${e.finished?'disabled':''}>${lottoPaused?'Продовжити':'Пауза'}</button><label class="speed-label">Темп<select aria-label="Темп розіграшу" id="lotto-speed">${[[2400,'Звичайний'],[700,'Швидкий']].map(([v,t])=>`<option value="${v}" ${activeGame.speed===v?'selected':''}>${t}</option>`).join('')}</select></label></div><details class="log-details"><summary>Усі числа (${e.called.length})</summary><p>${e.called.join(' · ')||'Числа ще не витягувалися'}</p></details>`;}
function resultHTML(){const g=activeGame,e=g.engine,win=e.winners.includes(0),record=state.history.find(r=>r.id===g.recordId);return `<div class="game-result" role="status"><span class="result-symbol">${win?'✦':'◇'}</span><h2>${win?(e.winners.length>1?'Банк поділено!':'Твоя перемога!'):'Партію завершено'}</h2><p>${e.winners.length>1?'Переможці':'Переможець'}: ${escapeHTML(e.winners.map(i=>g.names[i]).join(', '))}</p><small>${escapeHTML(e.reason)}${g.room.game==='telephone'?` · Рахунок: ${e.scores.join(' / ')}`:''}</small><strong class="result-net">${record?.net>=0?'+':''}${fmt(record?.net||0)} фішок</strong><div class="result-actions"><button class="button gold" data-action="rematch">Зіграти ще</button><button class="button ghost" data-action="navigate" data-page="rooms">До кімнат</button></div></div>`;}
function renderProfile(){const played=state.history.filter(r=>r.status!=='interrupted'),wins=played.filter(r=>r.status==='win'||r.status==='draw').length;main.innerHTML=heading('Мій профіль','Твій профіль у цьому демо-клубі.')+`<div class="profile-layout"><section class="panel profile-card"><span class="avatar profile-avatar ${state.profile.color}">${escapeHTML(state.profile.name[0])}</span><h2>${escapeHTML(state.profile.name)}</h2><span class="pill">ДЕМО-ГРАВЕЦЬ</span><div class="profile-balance">${fmt(state.balance)} <span>фішок</span></div><button class="button gold" data-action="wallet">Демо-гаманець</button></section><section class="panel"><h2>Налаштування профілю</h2><form id="profile-form"><label class="form-field">Ім’я за столом<input name="name" value="${escapeHTML(state.profile.name)}" minlength="2" maxlength="24" required></label><label class="form-field">Колір аватара<select name="color"><option value="rose" ${state.profile.color==='rose'?'selected':''}>Бордовий</option><option value="violet" ${state.profile.color==='violet'?'selected':''}>Фіолетовий</option><option value="amber" ${state.profile.color==='amber'?'selected':''}>Золотий</option></select></label><button class="button gold" type="submit">Зберегти зміни</button></form><p class="small-note">Демо-профіль не потребує пароля. Ім’я, фішки та історія зберігаються в цьому браузері.</p></section></div><div class="stat-grid"><div class="stat-card"><span>Зіграно партій</span><strong>${played.length}</strong></div><div class="stat-card"><span>Перемоги та нічиї</span><strong>${wins}</strong></div><div class="stat-card"><span>Частка перемог</span><strong>${played.length?Math.round(wins/played.length*100):0}%</strong></div></div>`;}
function historyTable(records){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Гра / кімната</th><th>Дата</th><th>Результат</th><th>Фішки</th></tr></thead><tbody>${records.map(r=>`<tr><td><strong>${titles[r.game]}</strong><small>${escapeHTML(r.room)}</small></td><td>${date(r.date)}</td><td><span class="status ${r.status}">${({win:'Перемога',draw:'Нічия',loss:'Поразка',interrupted:activeGame?.recordId===r.id&&!activeGame.settled?'У грі':'Перервано'})[r.status]||'Перервано'}</span></td><td class="${r.net>0?'positive':'negative'}">${r.net>0?'+':''}${fmt(r.net)} ◆</td></tr>`).join('')}</tbody></table></div>`;}
function renderHistory(){main.innerHTML=heading('Історія партій','Результати твоїх ігор та зміни балансу.')+(state.history.length?historyTable(state.history):'<div class="empty"><h2>Перша партія ще попереду</h2><p>Сідай за стіл — результат з’явиться тут.</p><button class="button gold" data-action="navigate" data-page="rooms">Обрати кімнату</button></div>');}
function renderRating(){const wins=state.history.filter(r=>r.status==='win'||r.status==='draw').length;const list=[{name:'Марко',wins:38,games:62},{name:'Софія',wins:31,games:54},{name:'Денис',wins:24,games:49},{name:state.profile.name,wins,games:state.history.filter(r=>r.status!=='interrupted').length,you:true}].sort((a,b)=>b.wins-a.wins);main.innerHTML=heading('Рейтинг клубу','Твій результат поруч із демонстраційними гравцями.')+`<div class="ranking-panel">${list.map((r,i)=>`<div class="rank-row ${r.you?'your-rank':''}"><span class="rank-number">${String(i+1).padStart(2,'0')}</span><span class="avatar ${r.you?state.profile.color:'bot-avatar'}">${escapeHTML(r.name[0])}</span><div><strong>${escapeHTML(r.name)}</strong><small>${r.you?'Твій локальний профіль':'Демо-гравець · приклад статистики'}</small></div><div class="rank-wins"><strong>${r.wins}</strong><small>перемог</small></div><span class="rank-games">${r.games} партій</span></div>`).join('')}</div><p class="small-note">Рейтинг ботів показує приклад оформлення. Твої перемоги рахуються з історії цього браузера.</p>`;}
function renderAdmin(){const completed=state.history.filter(r=>r.status!=='interrupted');main.innerHTML=heading('Панель адміністратора','Демо-керування кімнатами та локальна статистика.','<span class="pill">ДЕМО-ДОСТУП</span>')+`<div class="stat-grid"><div class="stat-card"><span>Відкриті кімнати</span><strong>${state.rooms.filter(r=>r.open).length}</strong></div><div class="stat-card"><span>Завершені партії</span><strong>${completed.length}</strong></div><div class="stat-card"><span>Внески за всі входи</span><strong>${fmt(state.history.reduce((s,r)=>s+r.stake,0))} ◆</strong></div></div><div class="section-heading"><h2>Керування кімнатами</h2><button class="text-button" data-action="create-room">Додати кімнату</button></div>`+roomRows(state.rooms,true)+`<div class="section section-heading"><h2>Останні партії</h2></div>${state.history.length?historyTable(state.history.slice(0,5)):'<p class="muted">Ще немає зіграних партій.</p>'}<div class="demo-strip"><span class="strip-icon">◇</span><p>Адмінпанель відкрита для демонстрації. У повній версії доступ матиме лише адміністратор.</p></div>`;}
function wallet(){showModal('Демо-гаманець',`<div class="wallet-total">${fmt(state.balance)} <span>◆</span></div><p>Це умовні фішки для перевірки ігор. Вони не мають грошової вартості.</p><div class="modal-actions"><button class="button gold" data-action="add-chips">Додати 1 000 фішок</button></div>`);}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target||target.disabled)return;const a=target.dataset.action;
  if(a==='navigate')navigate(target.dataset.page);if(a==='rooms')navigate('rooms',target.dataset.game||'all');if(a==='filter'){filter=target.dataset.filter;render();}if(a==='rules')rules();if(a==='game-rules')rules(activeGame?.room.game);if(a==='close')modal.close();if(a==='create-room')createRoom();if(a==='join')joinRoom(target.dataset.id);if(a==='start')startGame(target.dataset.id);if(a==='profile')navigate('profile');if(a==='wallet')wallet();if(a==='add-chips'){if(state.balance>999000){toast('Для демо вже достатньо фішок');return;}state.balance+=1000;save();wallet();toast('Додано 1 000 демо-фішок');}
  if(a==='toggle-room'){const room=state.rooms.find(r=>r.id===target.dataset.id);if(room){room.open=!room.open;save();render();toast(room.open?'Кімнату відкрито':'Кімнату закрито');}}
  if(a==='select-tile'){if(activeGame?.engine.turn!==0||activeGame.engine.finished)return;activeGame.selected=Number(target.dataset.index);renderGame();}if(a==='play-tile')playerDomino('play',activeGame?.selected,target.dataset.side);if(a==='draw-tile')playerDomino('draw');if(a==='pass')playerDomino('pass');if(a==='next-number')drawLotto();if(a==='pause-lotto'){lottoPaused=!lottoPaused;clearTimeout(lottoTimer);renderGame();schedule();}if(a==='leave-game'){if(activeGame?.settled){activeGame=null;navigate('rooms');}else confirmLeave(()=>navigate('rooms'));}if(a==='rematch'&&activeGame?.settled)joinRoom(activeGame.room.id);
});
document.addEventListener('submit',event=>{if(event.target.id==='profile-form'){event.preventDefault();const values=new FormData(event.target),name=String(values.get('name')).trim();if(name.length<2||name.length>24){toast('Ім’я має містити 2–24 символи');return;}state.profile={name,color:String(values.get('color'))};save();render();toast('Профіль збережено');}if(event.target.id==='room-form'){event.preventDefault();const values=new FormData(event.target),name=String(values.get('name')).trim(),game=values.get('game'),stake=Number(values.get('stake')),seats=Number(values.get('seats'));if(!name||name.length>40||!Object.hasOwn(titles,game)||![10,25,50,100].includes(stake)||![2,4].includes(seats)){toast('Перевір налаштування кімнати');return;}if(state.rooms.length>=30){toast('У демо доступно до 30 кімнат');return;}state.rooms.push({id:crypto.randomUUID(),name,game,stake,seats,open:true});save();modal.close();navigate('rooms',game);toast('Кімнату створено');}});
document.addEventListener('change',event=>{if(event.target.id==='lotto-speed'&&activeGame?.room.game==='lotto'){activeGame.speed=Number(event.target.value);clearTimeout(lottoTimer);schedule();}});
modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)modal.close();}});
window.addEventListener('beforeunload',event=>{if(activeGame&&!activeGame.settled){event.preventDefault();event.returnValue='';}});
updateAccount();render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const tool of [{name:'read_demo_club',description:'Read the local demo balance, open rooms and game status.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({balance:state.balance,rooms:state.rooms.filter(r=>r.open).map(r=>({...r})),game:activeGame?{mode:activeGame.room.game,finished:activeGame.engine.finished}:null})},{name:'navigate_demo_club',description:'Open a section of the demo club. Does not start a game or spend chips. Fails during an unfinished game.',inputSchema:{type:'object',properties:{page:{type:'string',enum:Object.keys(labels)}},required:['page'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!Object.hasOwn(labels,input.page))throw Error('Invalid section');if(activeGame&&!activeGame.settled)throw Error('Finish or leave the active game first');navigate(input.page);return {page};}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
